using UnityEngine;
// Exists only in the explicit development comparison scene. All mutations are detached runtime copies.
[DefaultExecutionOrder(-20)]public sealed class TrainingCombatComparison:MonoBehaviour {
 public TrainingFormulaProfile subtraction,attenuation;public TrainingFighter player;public TrainingOverlay overlay;
 public bool Ready{get;private set;}public string Status{get;private set;}="";public int Mode{get;private set;}public int ComboCount{get;private set;}public int MaxCombo{get;private set;}
 public TrainingFormulaProfile Active=>drafts==null?null:drafts[Mode];TrainingFormulaProfile[] drafts;TrainingMoveSet original,runtime;int observed;TrainingResolvedContact last;
 public bool DeveloperAllowed=>Application.isEditor||Debug.isDebugBuild;
 void Awake(){if(GetComponent<CombatTestV01>()!=null){enabled=false;return;}if(!DeveloperAllowed){enabled=false;return;}if(player==null||subtraction==null||attenuation==null||!subtraction.Validate(out _)||!attenuation.Validate(out _)){Status="Invalid comparison profile; comparison disabled";enabled=false;return;}
  original=player.moveSet==null?Resources.Load<TrainingMoveSet>("TrainingMoveSet"):player.moveSet;runtime=Instantiate(original);runtime.name="3P comparison runtime clone";drafts=new[]{Instantiate(subtraction),Instantiate(attenuation)};
  foreach(var command in new[]{TrainingCommand.Light,TrainingCommand.Medium,TrainingCommand.Heavy}){var move=runtime.Find(command);if(move==null){Status="Missing P move";enabled=false;return;}move.strength=new TrainingAttackStrength{enabled=true,weakPoint=new Vector3(0,move.center.y,move.center.z-move.halfSize.z),strongPoint=new Vector3(0,move.center.y,move.center.z+move.halfSize.z)};}
  player.moveSet=runtime;Ready=true;ApplyProfile();
 }
 void Start(){if(!Ready)return;player.ResetTraining();Status="DEV ONLY | runtime drafts; Inspector SOs are persistent authoring sources";}
 void ApplyProfile(){foreach(var entry in Active.moves){var move=runtime.Find(entry.command);move.strength.minimumLevel=entry.minimumAttack;move.strength.maximumLevel=entry.maximumAttack;}player.ComparisonProfile=Active;}
 public bool SetMode(int mode){if(!Ready||mode<0||mode>1)return false;Mode=mode;ApplyProfile();ResetTrial();Status="Mode changed; trial reset. 共通時間を維持。判定・連係先は変更なし。";return true;}
 public bool Edit(TrainingCommand command,float minimum,float maximum,float defense,float threshold,float chip){if(!Ready)return false;var e=Active.Find(command);if(e==null)return false;var candidate=e.Copy();candidate.minimumAttack=minimum;candidate.maximumAttack=maximum;candidate.defenseMultiplier=defense;candidate.threshold=threshold;candidate.guardDamageScale=chip;if(!candidate.Valid){Status="Invalid draft: finite nonnegative values, max >= min, chip 0..1";return false;}e.minimumAttack=minimum;e.maximumAttack=maximum;e.defenseMultiplier=defense;e.threshold=threshold;e.guardDamageScale=chip;ApplyProfile();ResetTrial();Status="Valid session draft; source SO unchanged";return true;}
 public void ResetDraft(){if(!Ready)return;var source=Mode==0?subtraction:attenuation;JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(source),Active);ApplyProfile();ResetTrial();Status="Restored profile SO defaults; no SO write";}
 public TrainingComparisonTiming Timing(TrainingCommand command){var move=runtime==null?null:runtime.Find(command);return IsPunch(command)&&move!=null?TrainingComparisonTiming.From(move):null;}
 static bool IsPunch(TrainingCommand command)=>command==TrainingCommand.Light||command==TrainingCommand.Medium||command==TrainingCommand.Heavy;
 public bool EditTiming(TrainingCommand command,float startup,float active,float recovery){if(!Ready||!IsPunch(command))return false;var draft=new TrainingComparisonTiming{startup=startup,active=active,recovery=recovery};if(!draft.Validate(out var error)){Status=error;return false;}ResetTrial();draft.Apply(runtime.Find(command));Status="時間ドラフトを反映・試行リセット。両計算式で共通、元の技SOは変更なし";return true;}
 public void ResetTimings(){if(!Ready)return;foreach(var command in new[]{TrainingCommand.Light,TrainingCommand.Medium,TrainingCommand.Heavy})if(!TrainingComparisonTiming.From(original.Find(command)).Validate(out var error)){Status="元データが無効: "+error;return;}ResetTrial();foreach(var command in new[]{TrainingCommand.Light,TrainingCommand.Medium,TrainingCommand.Heavy})TrainingComparisonTiming.From(original.Find(command)).Apply(runtime.Find(command));Status="共通時間を元の技SO値へ復元。式ごとの調整は維持";}

 public void ResetTrial(){if(player!=null)player.ResetTraining();ComboCount=0;MaxCombo=0;last=null;observed=player==null||player.opponent==null?0:player.opponent.ContactSequence;}
 void LateUpdate(){if(!Ready)return;var target=player.opponent;if(target.ContactSequence!=observed){observed=target.ContactSequence;last=target.LastResolvedContact;if(last!=null){if(last.hit)ComboCount=last.continuedCombo?ComboCount+1:1;else ComboCount=0;MaxCombo=Mathf.Max(MaxCombo,ComboCount);}}if(last!=null&&target.LastResolvedContact==null){last=null;ComboCount=0;MaxCombo=0;}}
 void OnGUI(){if(!Ready||overlay!=null&&overlay.OptionVisible)return;float width=Mathf.Min(900,Screen.width-20);var rect=new Rect(10,140,width,200);GUI.Box(rect,"");string text="DEV 3P COMPARISON | "+Active.formula+" | Esc > Combat compare\nJ/K/L = weak/mid/strong P | A/D move | R reset | Existing contact chains: weak -> mid -> strong\nAttack / hurtbox outlines; YELLOW selected part | Approved P active poses / standing guard / backward walk\n";
 if(last==null)text+="No contact yet. Approved key poses; same geometry/frames/chains in both modes.";else text+=$"Part {last.partId} | weakest A {last.rawAttack:0.00} | effective A {last.effectiveAttack:0.00} | D {last.defense:0.00}\nFinal {last.finalResult:0.00} > threshold {last.threshold:0.00}: {(last.hit?"HIT":"GUARD")} | damage {last.damage:0.00}\nStun {last.stunFrames:0.00}F | hitstop {last.hitstopFrames:0.00}F | combo {ComboCount} / max {MaxCombo} | chain cancels {player.ChainCount}";
 text+="\nExperimental attenuation: A/(1+D/100), threshold 100, guard damage 1/10. Stun/stop retain legacy formulas.";var labelStyle=new GUIStyle(GUI.skin.label){fontSize=14,wordWrap=true};GUI.Label(new Rect(rect.x+9,rect.y+5,rect.width-18,rect.height-10),text,labelStyle);

 }
 void OnDestroy(){if(player!=null&&player.moveSet==runtime){player.moveSet=original;player.ComparisonProfile=null;}if(runtime!=null)Destroy(runtime);if(drafts!=null)foreach(var draft in drafts)if(draft!=null)Destroy(draft);}
}
